/* Las dos tablas de INVT-01. Sin un color literal: todo de tokens.

   Tokens que faltaban (se usa el más cercano y se dice aquí, §6.1):
   - El texto del badge `Admin` del HTML aprobado es un brass oscuro (#92702e)
     que no está en la paleta; se usa `--bw-brass`.
   - No hay token de blanco puro: el fondo del botón de acción usa
     `--bw-warm-cream`, el más claro de la paleta. */

.sectionTitle {
  margin-top: 28px;
  margin-bottom: 10px;
  font-family: var(--bw-font-title);
  font-weight: 600;
  font-size: var(--bw-size-label);
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-divider);
  color: var(--bw-steel-mist);
}

.wrap {
  overflow-x: auto;
  margin-bottom: 8px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 5px;
}

.table {
  width: 100%;
  border-collapse: collapse;
  font-size: var(--bw-size-input);
}

.th {
  padding: 9px 14px;
  background: var(--bw-surface-mist);
  border-bottom: 1px solid var(--bw-line-steel);
  text-align: left;
  font-family: var(--bw-font-title);
  font-weight: 600;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: 0.07em;
  color: var(--bw-steel-mist);
  white-space: nowrap;
}

.td {
  padding: 11px 14px;
  border-bottom: 1px solid var(--bw-divider-mist);
  color: var(--bw-ink-steel);
  vertical-align: middle;
}

.table tbody tr:last-child .td {
  border-bottom: none;
}

.table tbody tr:hover .td {
  background: var(--bw-row-hover-tint);
}

.mono {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-label);
}

.expiresPending {
  color: var(--bw-brass);
}

.emptyCell {
  padding: 14px;
  text-align: center;
  color: var(--bw-steel-mist);
  font-size: var(--bw-size-input);
}

/* ── Insignias ──────────────────────────────────────────────────────────── */

.badge {
  display: inline-block;
  padding: 2px 7px;
  border-radius: 2px;
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-hint);
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-brand);
  white-space: nowrap;
}

.badgePending {
  background: var(--bw-chip-active-bg);
  border: 1px solid var(--bw-chip-active-border);
  color: var(--bw-primary-dark);
}

.badgeAccepted {
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  color: var(--bw-success-dark);
}

.badgeExpired {
  background: var(--bw-badge-neutral-bg);
  border: 1px solid var(--bw-badge-neutral-border);
  color: var(--bw-ink-steel-soft);
}

.badgeAdmin {
  background: var(--bw-tag-bg);
  border: 1px solid var(--bw-tag-border);
  color: var(--bw-brass);
}

.badgeEditor {
  background: var(--bw-badge-neutral-bg);
  border: 1px solid var(--bw-badge-neutral-border);
  color: var(--bw-ink-steel-soft);
}

.badgeActive {
  background: var(--bw-badge-success-bg);
  border: 1px solid var(--bw-badge-success-border);
  color: var(--bw-success-dark);
}

.badgeSuspended {
  background: var(--bw-sensitive-bg);
  border: 1px solid var(--bw-badge-danger-border);
  color: var(--bw-sensitive-text);
}

.badgeNeutral {
  background: var(--bw-badge-neutral-bg);
  border: 1px solid var(--bw-badge-neutral-border-soft);
  color: var(--bw-ink-steel-soft);
}

/* ── Acciones ───────────────────────────────────────────────────────────── */

.actionButton {
  padding: 4px 10px;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: var(--bw-size-label);
  color: var(--bw-ink-steel);
  cursor: pointer;
  transition: border-color 0.15s ease, color 0.15s ease, background 0.15s ease;
}

.actionButton:hover:not(:disabled) {
  border-color: var(--bw-brass);
  color: var(--bw-brass);
}

.actionButton:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.actionDanger {
  background: var(--bw-sensitive-bg);
  border-color: var(--bw-badge-danger-border);
  color: var(--bw-error-text);
}

.actionDanger:hover:not(:disabled) {
  background: var(--bw-danger-hover-bg);
  border-color: var(--bw-danger);
  color: var(--bw-error-text);
}

.none {
  font-size: var(--bw-size-label);
  color: var(--bw-line-steel-strong);
}

import {
  CANNOT_REMOVE_OWN_ADMIN,
  canRemove,
  expiresInLabel,
  memberStateLabel,
  roleLabel,
  sentAtLabel,
  type InvitationRow,
  type InvitationStatus,
  type TeamMember,
} from '../../lib/invitations';
import styles from './InvitationTables.module.css';

interface Props {
  invitations: InvitationRow[];
  team: TeamMember[];
  selfId: string;
  busy: boolean;
  onResend: (invitationId: string) => void;
  onRemove: (member: TeamMember) => void;
}

/** El otro motivo del guion: el rol que no se puede eliminar (spec, HTML aprobado). */
const CANNOT_REMOVE_ROLE = 'Solo se pueden eliminar usuarios con rol Editor';

const EMPTY_INVITATIONS = 'Todavía no has enviado ninguna invitación.';

/**
 * Las dos tablas de INVT-01. Presentacional: no llama a la red y no guarda
 * estado. Decide a quién le toca botón y a quién le toca guion con las funciones
 * puras de la capa de datos — `canRemove` sobre todo, para que la fila del propio
 * ADMIN y la del que no es Editor se expliquen solas.
 */
export function InvitationTables({ invitations, team, selfId, busy, onResend, onRemove }: Props) {
  return (
    <>
      <section>
        <h2 className={styles.sectionTitle}>Invitaciones enviadas</h2>
        <div className={styles.wrap}>
          <table className={styles.table} aria-label="Invitaciones enviadas">
            <thead>
              <tr>
                <th scope="col" className={styles.th}>
                  Email
                </th>
                <th scope="col" className={styles.th}>
                  Estado
                </th>
                <th scope="col" className={styles.th}>
                  Fecha de envío
                </th>
                <th scope="col" className={styles.th}>
                  Expira en
                </th>
                <th scope="col" className={styles.th}>
                  Acciones
                </th>
              </tr>
            </thead>
            <tbody>
              {invitations.length === 0 ? (
                <tr>
                  <td className={styles.emptyCell} colSpan={5}>
                    {EMPTY_INVITATIONS}
                  </td>
                </tr>
              ) : (
                invitations.map((invitation) => (
                  <tr key={invitation.id}>
                    <td className={`${styles.td} ${styles.mono}`}>{invitation.email}</td>
                    <td className={styles.td}>
                      <span className={statusClass(invitation.status)}>{invitation.status}</span>
                    </td>
                    <td className={`${styles.td} ${styles.mono}`}>{sentAtLabel(invitation.sentAt)}</td>
                    <td className={expiresClass(invitation.status)}>{expiresInLabel(invitation.daysLeft)}</td>
                    <td className={styles.td}>
                      {invitation.status === 'Expirada' ? (
                        <button
                          type="button"
                          className={styles.actionButton}
                          aria-label={`Reenviar ${invitation.email}`}
                          disabled={busy}
                          onClick={() => onResend(invitation.id)}
                        >
                          Reenviar
                        </button>
                      ) : (
                        <span className={styles.none}>—</span>
                      )}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </section>

      <section>
        <h2 className={styles.sectionTitle}>Usuarios activos</h2>
        <div className={styles.wrap}>
          <table className={styles.table} aria-label="Usuarios activos">
            <thead>
              <tr>
                <th scope="col" className={styles.th}>
                  Nombre
                </th>
                <th scope="col" className={styles.th}>
                  Email
                </th>
                <th scope="col" className={styles.th}>
                  Rol
                </th>
                <th scope="col" className={styles.th}>
                  Estado
                </th>
                <th scope="col" className={styles.th}>
                  Acciones
                </th>
              </tr>
            </thead>
            <tbody>
              {team.map((member) => (
                <tr key={member.id}>
                  <td className={styles.td}>{member.fullName}</td>
                  <td className={`${styles.td} ${styles.mono}`}>{member.email}</td>
                  <td className={styles.td}>
                    <span className={roleClass(member.role)}>{roleLabel(member.role)}</span>
                  </td>
                  <td className={styles.td}>
                    <span className={stateClass(member.state)}>{memberStateLabel(member.state)}</span>
                  </td>
                  <td className={styles.td}>
                    {canRemove(member, selfId) ? (
                      <button
                        type="button"
                        className={`${styles.actionButton} ${styles.actionDanger}`}
                        aria-label={`Eliminar ${member.fullName}`}
                        disabled={busy}
                        onClick={() => onRemove(member)}
                      >
                        Eliminar
                      </button>
                    ) : (
                      <span
                        className={styles.none}
                        title={member.id === selfId ? CANNOT_REMOVE_OWN_ADMIN : CANNOT_REMOVE_ROLE}
                      >
                        —
                      </span>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </section>
    </>
  );
}

function statusClass(status: InvitationStatus): string {
  if (status === 'Aceptada') return `${styles.badge} ${styles.badgeAccepted}`;
  if (status === 'Expirada') return `${styles.badge} ${styles.badgeExpired}`;
  return `${styles.badge} ${styles.badgePending}`;
}

/** El plazo en brass SOLO en las pendientes: en las demás la celda es un guion. */
function expiresClass(status: InvitationStatus): string {
  const base = `${styles.td} ${styles.mono}`;
  return status === 'Pendiente' ? `${base} ${styles.expiresPending}` : base;
}

function roleClass(role: TeamMember['role']): string {
  return role === 'ADMIN' ? `${styles.badge} ${styles.badgeAdmin}` : `${styles.badge} ${styles.badgeEditor}`;
}

function stateClass(state: string): string {
  if (state === 'ACTIVE') return `${styles.badge} ${styles.badgeActive}`;
  if (state === 'SUSPENDED') return `${styles.badge} ${styles.badgeSuspended}`;
  return `${styles.badge} ${styles.badgeNeutral}`;
}

