/* Confirmación de eliminación de INVT-01. Sin un color literal.

   Nota de tokens que faltan (se usa el más cercano y se dice aquí, §6.1):
   - No hay token de blanco puro: el fondo del diálogo y el texto sobre el botón
     rojo usan `--bw-warm-cream`, el más claro de la paleta. */

.overlay {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  background: var(--bw-sidebar-overlay);
}

.dialog {
  width: 100%;
  max-width: 420px;
  box-sizing: border-box;
  padding: 28px;
  background: var(--bw-warm-cream);
  border-radius: 6px;
  box-shadow: 0 20px 60px var(--bw-sidebar-overlay);
  font-family: var(--bw-font-body);
  color: var(--bw-deep-steel);
}

.title {
  font-family: var(--bw-font-title);
  font-weight: 700;
  font-size: 17px;
  color: var(--bw-deep-steel);
  margin-bottom: 10px;
}

.person {
  display: flex;
  flex-direction: column;
  gap: 2px;
  margin-bottom: 14px;
}

.name {
  font-size: 14px;
  font-weight: 600;
  color: var(--bw-deep-steel);
}

.email {
  font-family: var(--bw-font-mono);
  font-size: var(--bw-size-label);
  color: var(--bw-steel-mist);
}

.warning {
  padding: 10px 12px;
  margin-bottom: 20px;
  background: var(--bw-sensitive-bg);
  border-left: 3px solid var(--bw-danger);
  border-radius: 0 var(--bw-radius) var(--bw-radius) 0;
  font-size: var(--bw-size-label);
  line-height: 1.5;
  color: var(--bw-sensitive-text);
}

.error {
  margin-bottom: 14px;
  font-size: var(--bw-size-label);
  color: var(--bw-error-text);
}

.actions {
  display: flex;
  gap: 10px;
}

.cancel {
  flex: 1;
  padding: 10px;
  background: var(--bw-warm-cream);
  border: 1px solid var(--bw-line-steel-strong);
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: 14px;
  font-weight: 500;
  color: var(--bw-ink-steel);
  cursor: pointer;
  transition: background 0.15s ease;
}

.cancel:hover:not(:disabled) {
  background: var(--bw-cold-white);
}

.cancel:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

.confirm {
  flex: 1;
  padding: 10px;
  background: var(--bw-danger);
  border: none;
  border-radius: var(--bw-radius);
  font-family: var(--bw-font-body);
  font-size: 14px;
  font-weight: 600;
  color: var(--bw-warm-cream);
  cursor: pointer;
  transition: background 0.15s ease;
}

.confirm:hover:not(:disabled) {
  background: var(--bw-sensitive-text);
}

.confirm:disabled {
  opacity: 0.5;
  cursor: not-allowed;
}

import { useEffect, useRef } from 'react';
import type { TeamMember } from '../../lib/invitations';
import styles from './RemoveMemberDialog.module.css';

interface Props {
  member: TeamMember;
  busy: boolean;
  error: string | null;
  onConfirm: () => void;
  onCancel: () => void;
}

const TITLE_ID = 'remove-member-title';

const WARNING = 'Esta acción es irreversible. El usuario perderá acceso inmediatamente.';

/**
 * La confirmación de INVT-01. Presentacional: NO elimina nada, solo pregunta.
 *
 * Dos cosas que el componente tiene que hacer por sí mismo porque nadie más
 * puede: llevarse el foco al botón `Cancelar` al abrirse (la acción segura es la
 * que menos se pulsa) y escuchar Escape en `document` mientras está montado.
 * Nada de `window.confirm`: el diálogo es este.
 */
export function RemoveMemberDialog({ member, busy, error, onConfirm, onCancel }: Props) {
  const cancelRef = useRef<HTMLButtonElement>(null);

  useEffect(() => {
    cancelRef.current?.focus();
  }, []);

  useEffect(() => {
    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === 'Escape') onCancel();
    }

    document.addEventListener('keydown', handleKeyDown);
    return () => {
      document.removeEventListener('keydown', handleKeyDown);
    };
  }, [onCancel]);

  return (
    <div className={styles.overlay}>
      <div role="dialog" aria-modal="true" aria-labelledby={TITLE_ID} className={styles.dialog}>
        <h2 id={TITLE_ID} className={styles.title}>
          Eliminar usuario
        </h2>
        <div className={styles.person}>
          <span className={styles.name}>{member.fullName}</span>
          <span className={styles.email}>{member.email}</span>
        </div>
        <p className={styles.warning}>{WARNING}</p>
        {error !== null && (
          <p className={styles.error} role="alert">
            {error}
          </p>
        )}
        <div className={styles.actions}>
          <button
            ref={cancelRef}
            type="button"
            className={styles.cancel}
            onClick={onCancel}
            disabled={busy}
          >
            Cancelar
          </button>
          <button
            type="button"
            className={styles.confirm}
            onClick={onConfirm}
            disabled={busy}
          >
            Eliminar
          </button>
        </div>
      </div>
    </div>
  );
}
